const board = $('📋 G54: Buscar Deal Existente (CRM)').item.json;

let wa_contact_id = null;
try {
  const contactData = $('🔍 Buscar Contact ID (G54)').item.json.data || [];
  wa_contact_id = contactData[0]?.id || null;
} catch (e) { /* si falló el lookup, seguimos sin el vínculo */ }

// Community AI (FB/IG) nunca tiene un teléfono real — el usuarioId de Facebook
// se usa solo como clave interna para G54 (endpoints /inbound y /wa/leads lo piden
// como "phone"), pero no se muestra como teléfono en el CRM para no inventar uno.
let match = null;
try {
  for (const etapa of Object.keys(board)) {
    const deals = board[etapa] || [];
    const found = deals.find(d => wa_contact_id && d.wa_contact_id === wa_contact_id);
    if (found) { match = found; break; }
  }
} catch (e) { /* si el board no cargó, seguimos como si no existiera */ }

return [{ json: {
  existe: !!match,
  deal_id: match ? match.id : null,
  wa_contact_id,
}}];

const evento = $('🔍 Extraer Evento FB/IG').item.json;
const config = $('🏢 Aplicar Config Empresa').item.json;
const resp = $input.item.json;

const miId = evento.plataforma === 'instagram' ? config.IG_USER_ID : config.FB_PAGE_ID;

let yaRespondido = false;
try {
  const items = resp.data || [];
  yaRespondido = items.some(c => (c.from && c.from.id) === miId);
} catch (e) {
  yaRespondido = false;
}

return [{ json: { yaRespondido } }];

const dealResp = $json;
const dealId = dealResp && dealResp.id ? dealResp.id : null;

let contenido = null;
try {
  const parsed = $('🔍 Parsear Respuesta Community AI').item.json;
  const lead = (parsed.lead || '').toLowerCase();
  if (lead === 'caliente') {
    contenido = 'Community AI: comentario/DM clasificado como lead caliente.';
  }
} catch (e) { /* si no se puede leer, no se loggea nada */ }

return [{ json: { dealId, contenido, deberiaLoggear: !!(dealId && contenido) } }];

